const rawProfiles = $('Read Raw Profiles').all();
let classified = [];
try {
  classified = $('Read Already Classified').all();
} catch (e) {
  classified = [];
}

const classifiedUsernames = new Set(
  classified
    .filter(item => item.json && item.json.username)
    .map(item => item.json.username.toLowerCase())
);

// Replica/fake keywords pre-filter - drop these before they ever reach Gemini
const replicaPattern = /\b(replica|1:1|superclone|super\s*clone|aaa\s*quality|clone|factory\s*direct|china\s*factory|noob\s*factory|clean\s*factory|vs\s*factory|fake|counterfeit|rep\s*watch|reptime|dhgate|mirror\s*quality)\b/i;

const seen = new Set();
const unclassified = [];

for (const profile of rawProfiles) {
  const username = (profile.json.username || '').trim().toLowerCase();
  if (!username) continue;
  if (seen.has(username)) continue;
  if (classifiedUsernames.has(username)) continue;

  // Check bio for replica/fake keywords - skip entirely if found
  const bio = (profile.json.bio || '').toLowerCase();
  if (replicaPattern.test(bio)) {
    profile.json._is_replica_prefiltered = true;
    seen.add(username);
    continue;
  }

  seen.add(username);
  unclassified.push(profile);
}

return unclassified.slice(0, 100);

// Prepare image URLs for Gemini vision analysis
// STRICTLY filter out video files (.mp4, .mov, .avi, .webm) - Gemini vision cannot process them reliably
const profile = $json;
const videoExtensions = /\.(mp4|mov|avi|webm|mkv|flv|wmv|m4v)([?#]|$)/i;

const imageUrlsRaw = (profile.image_urls || '').split(',').map(u => u.trim()).filter(u => {
  if (!u || !u.startsWith('http')) return false;
  if (videoExtensions.test(u)) return false;
  return true;
});

const videoUrlsRaw = (profile.video_urls || '').split(',').map(u => u.trim()).filter(u => u && u.startsWith('http'));

const seen = new Set();
const uniqueImages = [];
for (const url of imageUrlsRaw) {
  const normalized = url.split('?')[0];
  if (!seen.has(normalized)) {
    seen.add(normalized);
    uniqueImages.push(url);
  }
}

const imagesToAnalyze = uniqueImages.slice(0, 8);

return [{
  json: {
    ...profile,
    _images_to_analyze: imagesToAnalyze,
    _videos_to_analyze: [],
    _has_media: imagesToAnalyze.length > 0,
    _skipped_videos: videoUrlsRaw.length,
    _total_images_available: uniqueImages.length
  }
}];

// Build combined Gemini request - vision + classification in one call
