      phone_in_bio: flashResult.phone_in_bio,
      engagement_rate: flashResult.engagement_rate,
      profile_url: flashResult.profile_url,
      seed_account: flashResult.seed_account,
      seed_type: flashResult.seed_type,
      classification: flashResult.classification || 'error',
      confidence: flashResult.confidence || 'low',
      watch_brands: flashResult.watch_brands || '',
      specific_watches: flashResult.specific_watches || '',
      visible_recent_collection_value: flashResult.visible_recent_collection_value || 'unknown',
      watch_collection_rank: flashResult.watch_collection_rank || 1,
      wealth_tier: flashResult.wealth_tier || 'unknown',
      wealth_signals: flashResult.wealth_signals || '',
      ownership_type: flashResult.ownership_type || 'unclear',
      approach_suggestion: (flashResult.approach_suggestion || '').substring(0, 500),
      priority_score: flashResult.priority_score || 0,
      ai_reasoning: 'Pro verification failed, using Flash result. ' + (flashResult.ai_reasoning || ''),
      vision_summary: (flashResult.vision_summary || '').substring(0, 500),
      images_analyzed: flashResult.images_analyzed || 0,
      classified_date: new Date().toISOString().split('T')[0]
    }
  }];
}

// Enforce priority_score = MAX(watch_collection_rank, wealth_floor)
const wcr = Number(classification.watch_collection_rank) || 1;
const wt = (classification.wealth_tier || 'unknown').toLowerCase();
const wealthFloor = { 'ultra-high': 7, 'high': 5, 'standard': 3, 'unknown': 1 }[wt] || 1;
let enforced_priority = Math.max(wcr, wealthFloor);
if (wcr >= 7 && wt === 'ultra-high') enforced_priority = Math.min(10, enforced_priority + 1);
if (classification.classification === 'replica_dealer') enforced_priority = 0;
classification.priority_score = enforced_priority;
classification.watch_collection_rank = wcr;
classification.wealth_tier = wt;

const watchList = Array.isArray(classification.specific_watches)
  ? classification.specific_watches.map(w => {
      const wp = [w.brand, w.model, w.reference].filter(Boolean);
      const val = w.estimated_value_usd ? ' (~' + w.estimated_value_usd + ')' : '';
      return wp.join(' ') + val;
    }).join(' | ')
  : (classification.specific_watches || '');

const brands = Array.isArray(classification.watch_brands) ? classification.watch_brands.join(', ') : (classification.watch_brands || '');
const wealth = Array.isArray(classification.wealth_signals) ? classification.wealth_signals.join(', ') : (classification.wealth_signals || '');

return [{
  json: {
    username: flashResult.username,
    platform: flashResult.platform || 'instagram',
    full_name: flashResult.full_name,
    bio: (flashResult.bio || '').substring(0, 500),
    follower_count: flashResult.follower_count,
    following_count: flashResult.following_count,
    post_count: flashResult.post_count,
    is_verified: flashResult.is_verified,
    is_business: flashResult.is_business,
    business_category: flashResult.business_category,
    external_url: flashResult.external_url,
    email_in_bio: flashResult.email_in_bio,
    phone_in_bio: flashResult.phone_in_bio,
    engagement_rate: flashResult.engagement_rate,
    profile_url: flashResult.profile_url,
    seed_account: flashResult.seed_account,
    seed_type: flashResult.seed_type,
    classification: classification.classification || 'unknown',
    confidence: classification.confidence || 'low',
    watch_brands: brands,
    specific_watches: watchList,
    visible_recent_collection_value: classification.visible_recent_collection_value || 'unknown',
    watch_collection_rank: classification.watch_collection_rank || 1,
    wealth_tier: classification.wealth_tier || 'unknown',
    wealth_signals: wealth,
    ownership_type: classification.ownership_type || 'unclear',
    approach_suggestion: (classification.approach_suggestion || '').substring(0, 500),
    priority_score: classification.priority_score || 0,
    ai_reasoning: (classification.reasoning || '').substring(0, 1000),
    vision_summary: (classification.image_summary || '').substring(0, 500),
    images_analyzed: downloadedCount,
    classified_date: new Date().toISOString().split('T')[0]
  }
}];
